package com.bank.decomposition.planner;

import java.util.Set;
import java.util.logging.Logger;

// Decides whether a proposed boundary is a GOOD cut (capability/subdomain)
// or a BAD cut (technical layer).
public class DecompositionPlanner {
    private static final Logger log = Logger.getLogger(DecompositionPlanner.class.getName());
    private static final Set<String> TECHNICAL_LAYERS =
        Set.of("ControllerService", "DatabaseService", "UtilService", "DtoService");

    public boolean isGoodBoundary(String proposedServiceName) {
        if (TECHNICAL_LAYERS.contains(proposedServiceName)) {
            log.severe("BAD cut: '" + proposedServiceName
                     + "' is a technical layer — every feature will span services");
            return false;
        }
        log.info("GOOD cut: '" + proposedServiceName
               + "' maps to a business capability / subdomain");
        return true;
    }
}
