package com.bank.decomposition.scaling;

import java.util.logging.Logger;

// Decompose by scalability: flag a component whose load differs sharply.
public class ScalabilityProfile {
    private static final Logger log = Logger.getLogger(ScalabilityProfile.class.getName());

    public boolean shouldExtractForScaling(String component, int peakMultiplier) {
        if (peakMultiplier >= 5) {
            log.warning(() -> component + " peaks at " + peakMultiplier
                            + "x — extract so it scales independently");
            return true;
        }
        log.info(() -> component + " load is average — no separate scaling needed");
        return false;
    }
}
