package com.bank.decomposition;

import com.bank.decomposition.capability.BusinessCapability;
import com.bank.decomposition.planner.DecompositionPlanner;
import com.bank.decomposition.scaling.ScalabilityProfile;
import java.util.logging.Logger;

public class DecompositionDemo {
    private static final Logger log = Logger.getLogger(DecompositionDemo.class.getName());

    public static void main(String[] args) {
        DecompositionPlanner planner = new DecompositionPlanner();
        ScalabilityProfile profile = new ScalabilityProfile();

        log.info("=== Reject technical-layer cuts ===");
        planner.isGoodBoundary("DatabaseService");

        log.info("=== Accept business-capability cuts ===");
        for (BusinessCapability c : BusinessCapability.values()) {
            planner.isGoodBoundary(c.name());
        }

        log.info("=== Decompose by scalability ===");
        profile.shouldExtractForScaling("PaymentService", 3);
        profile.shouldExtractForScaling("FraudDetectionService", 10);
    }
}
